CREATE TABLE IF NOT EXISTS `graph_icon`
(
    `id`          bigint       NOT NULL,
    `legend_id`   varchar(100) NOT NULL COMMENT '图标id',
    `file_url`    varchar(255)  DEFAULT NULL COMMENT '文件id',
    `pic_url`     varchar(1000) DEFAULT NULL COMMENT '文件url',
    `condition`   varchar(1000) DEFAULT NULL COMMENT '条件',
    `legend_code` varchar(100)  DEFAULT NULL COMMENT '图标编码',
    `legend_name` varchar(100)  DEFAULT NULL COMMENT '图标名称',
    `class_code`  varchar(40)  NOT NULL COMMENT '对象类code',
    `create_user` varchar(100)  DEFAULT NULL,
    `create_time` datetime     NOT NULL,
    `update_user` varchar(100)  DEFAULT NULL,
    `update_time` datetime     NOT NULL,
    `status`      int           DEFAULT NULL COMMENT '状态',
    PRIMARY KEY (`id`),
    KEY `index_graph_icon` (`legend_id`, `class_code`, `legend_name`)
) COMMENT ='图标库';


CREATE TABLE IF NOT EXISTS `graph_legend`
(
    `id`             bigint       NOT NULL,
    `legend_id`      varchar(100) NOT NULL COMMENT '图例id',
    `status`         tinyint               DEFAULT NULL COMMENT '状态',
    `file_url`       varchar(1000)         DEFAULT NULL COMMENT '图例对应图片id',
    `pic_url`        varchar(1000)         DEFAULT NULL COMMENT '文件url',
    `class_code`     varchar(40)  NOT NULL COMMENT '对象类code',
    `legend_code`    varchar(100)          DEFAULT NULL COMMENT '图例code',
    `obj_type`       varchar(100)          DEFAULT NULL COMMENT '对象类型',
    `legend_name`    varchar(100)          DEFAULT NULL COMMENT '图例名称',
    `attach_type`    tinyint               DEFAULT NULL COMMENT '是否是小附件，0不是，1是',
    `legend_version` int          NOT NULL DEFAULT '1' COMMENT '图例版本',
    `valid`          tinyint               DEFAULT NULL COMMENT '是否可用',
    `remark`         varchar(100)          DEFAULT NULL COMMENT '备注',
    `texts`          text COMMENT '文本框',
    `size`           varchar(100)          DEFAULT NULL COMMENT '尺寸',
    `anchors`        text COMMENT '锚点',
    `create_user`    varchar(100)          DEFAULT NULL,
    `create_time`    datetime     NOT NULL,
    `update_user`    varchar(100)          DEFAULT NULL,
    `update_time`    datetime     NOT NULL,
    PRIMARY KEY (`id`) USING BTREE,
    KEY `index_graph_legend` (`class_code`, `legend_id`, `status`) USING BTREE
) COMMENT ='图例库';

delete from `graph_legend`;


delete from `graph_icon`;
